<?php $rows=db()->query('SELECT * FROM objects ORDER BY object_name')->fetchAll(); ?>
<div class="panel"><h2>Objekte verwalten</h2><form class="ajax-form form-grid" action="ajax/objects.php" data-reload="objects" method="post"><?= csrfField() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="0"><label>Objektname<input name="object_name" required></label><label>Adresse<input name="address"></label><label>Status<select name="status"><option>aktiv</option><option>inaktiv</option></select></label><label>Startdatum<input type="date" name="start_date"></label><label>Enddatum<input type="date" name="end_date"></label><label>Notizen<textarea name="notes"></textarea></label><div><button>Objekt anlegen</button></div></form></div>
<div class="panel"><table class="data-table js-data-table"><thead><tr><th>Objektname</th><th>Adresse</th><th>Status</th><th>Startdatum</th><th>Enddatum</th><th>Aktionen</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['object_name']) ?></td><td><?= e($r['address']) ?></td><td><?= statusBadge($r['status']) ?></td><td><?= e($r['start_date']) ?></td><td><?= e($r['end_date']) ?></td><td><form class="ajax-form inline-form" action="ajax/objects.php" data-reload="objects" method="post"><?= csrfField() ?><input type="hidden" name="action" value="deactivate"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="secondary">inaktiv setzen</button></form></td></tr><?php endforeach; ?></tbody></table></div><script>initDataTable('.js-data-table');</script>
